import { useState, useEffect } from 'react'
import { ArrowLeft, ArrowRight } from 'lucide-react'
import { GENRES } from '../data/genres'
import { useCatalog } from '../lib/catalog-context'
import { SeriesCard } from '../components/SeriesCard'
import { navigate } from '../lib/router'
import { cx, formatViews, chapterCountOf } from '../lib/utils'
import { setSeo, buildStatusMeta } from '../lib/seo'
import type { SeriesStatus } from '../types'

const PAGE_SIZE = 60
const DAY = 86_400_000

const INTRO: Record<'ongoing' | 'completed', string> = {
  ongoing:
    'Series still releasing new chapters — follow any title and new chapters land in your library as they drop.',
  completed:
    'Finished series you can read start to end — complete chapter lists, no waiting for the next drop.',
}

const OTHER: Record<'ongoing' | 'completed', { status: 'ongoing' | 'completed'; title: string; blurb: string }> = {
  ongoing: {
    status: 'completed',
    title: 'Completed Manhwa',
    blurb: 'Binge a finished run from chapter one to the finale.',
  },
  completed: {
    status: 'ongoing',
    title: 'Ongoing Manhwa',
    blurb: 'Follow series that are still dropping new chapters.',
  },
}

export default function StatusPage({ status }: { status: 'ongoing' | 'completed' }) {
  const { series: catalog, loading } = useCatalog()
  const [sort, setSort] = useState<'trending' | 'rating' | 'newest' | 'popular'>('trending')
  const [shown, setShown] = useState(PAGE_SIZE)

  // Per-status metadata with real counts
  useEffect(() => {
    setSeo(
      buildStatusMeta(status, catalog.filter((s) => s.status === (status === 'ongoing' ? 'Ongoing' : 'Completed')).length),
    )
  }, [status, catalog.length])

  const match: SeriesStatus = status === 'ongoing' ? 'Ongoing' : 'Completed'

  let list = catalog.filter((s) => s.status === match)
  if (sort === 'trending') list = [...list].sort((a, b) => b.weeklyViews - a.weeklyViews)
  if (sort === 'rating') list = [...list].sort((a, b) => b.rating - a.rating)
  if (sort === 'newest') list = [...list].sort((a, b) => +new Date(b.firstReleased) - +new Date(a.firstReleased))
  if (sort === 'popular') list = [...list].sort((a, b) => b.views - a.views)

  const totalChapters = list.reduce((n, s) => n + chapterCountOf(s), 0)
  const updatedToday = list.filter(
    (s) => Date.now() - new Date(s.lastUpdated).getTime() < DAY,
  ).length
  const totalViews = list.reduce((n, s) => n + s.views, 0)

  const other = OTHER[status]
  const otherCount = catalog.filter(
    (s) => s.status === (other.status === 'ongoing' ? 'Ongoing' : 'Completed'),
  ).length

  return (
    <main className="animate-fade-up">
      {/* Banner */}
      <div
        className="border-b border-line"
        style={{
          background: 'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)',
        }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <button
            onClick={() => navigate('/catalog')}
            className="mb-6 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <ArrowLeft width={16} height={16} /> All Series
          </button>
          <div className="eyebrow text-accent">Publishing Status</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">
            {status === 'ongoing' ? 'Ongoing Manhwa' : 'Completed Manhwa'}
          </h1>
          <p className="mt-3 max-w-xl text-white/70">{INTRO[status]}</p>
          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/60">
            <span>
              <strong className="text-white">{loading ? '…' : list.length}</strong> series
            </span>
            <span>
              <strong className="text-white">{loading ? '…' : formatViews(totalChapters)}</strong>{' '}
              chapters
            </span>
            {status === 'ongoing' ? (
              <span>
                <strong className="text-white">{updatedToday}</strong> updated today
              </span>
            ) : (
              <span>
                <strong className="text-white">{formatViews(totalViews)}</strong> total views
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        {/* Sort bar */}
        <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
          <div className="text-sm text-ink-faint">
            {status === 'ongoing' ? 'Still updating' : 'Fully released'} in{' '}
            <strong className="text-ink">
              {status === 'ongoing' ? 'Ongoing' : 'Completed'}
            </strong>
          </div>
          <div className="flex gap-1.5">
            {(['trending', 'rating', 'newest', 'popular'] as const).map((k) => (
              <button
                key={k}
                onClick={() => setSort(k)}
                className={cx(
                  'rounded-full border px-3.5 py-1.5 text-xs font-semibold capitalize transition-colors',
                  sort === k
                    ? 'border-ink bg-ink text-paper'
                    : 'border-line-strong bg-paper text-ink-soft hover:border-ink hover:text-ink',
                )}
              >
                {k === 'trending' ? 'Trending' : k === 'rating' ? 'Highest Rated' : k === 'newest' ? 'Newest' : 'Most Popular'}
              </button>
            ))}
          </div>
        </div>

        {loading ? (
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {Array.from({ length: 10 }).map((_, i) => (
              <div key={i}>
                <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
                <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
              </div>
            ))}
          </div>
        ) : list.length === 0 ? (
          <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-20 text-center">
            <div className="text-lg font-bold">No stories found</div>
            <p className="mt-2 text-sm text-ink-soft">
              No series carry this publishing status right now.
            </p>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
              {list.slice(0, shown).map((s) => (
                <SeriesCard key={s.id} series={s} />
              ))}
            </div>
            {shown < list.length && (
              <div className="mt-10 text-center">
                <button
                  onClick={() => setShown((n) => n + PAGE_SIZE)}
                  className="inline-flex items-center gap-2 rounded-full border border-ink/25 bg-paper px-5 py-2.5 text-sm font-semibold text-ink transition-all hover:border-ink hover:bg-ink hover:text-paper"
                >
                  Show more
                  <span className="text-ink-faint">
                    {Math.min(PAGE_SIZE, list.length - shown)} of {list.length} left
                  </span>
                </button>
              </div>
            )}
          </>
        )}

        {/* Keep exploring */}
        <section className="mt-16">
          <div className="eyebrow mb-4 text-accent">Keep Exploring</div>
          <div className="grid gap-3 sm:grid-cols-3">
            <a
              href={`/status/${other.status}`}
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate(`/status/${other.status}`)
              }}
              className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
            >
              <div>
                <div className="font-extrabold tracking-tight group-hover:text-accent">{other.title}</div>
                <div className="mt-0.5 text-xs text-ink-faint">{otherCount} titles</div>
              </div>
              <ArrowRight width={18} height={18} className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent" />
            </a>
            <a
              href="/updates"
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate('/updates')
              }}
              className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
            >
              <div>
                <div className="font-extrabold tracking-tight group-hover:text-accent">Latest Updates</div>
                <div className="mt-0.5 text-xs text-ink-faint">Newest chapters</div>
              </div>
              <ArrowRight width={18} height={18} className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent" />
            </a>
            <a
              href="/genres"
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate('/genres')
              }}
              className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
            >
              <div>
                <div className="font-extrabold tracking-tight group-hover:text-accent">Genre Directory</div>
                <div className="mt-0.5 text-xs text-ink-faint">{GENRES.length} genres</div>
              </div>
              <ArrowRight width={18} height={18} className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent" />
            </a>
          </div>
        </section>
      </div>
    </main>
  )
}
